const baseStats=():Stats=>({performance:0,energy:GAME_RULES.energyPerRound,confidence:60,fatigue:10,injuryRisk:8});
const careerStats=(career:CareerProgress):Stats=>{const stats=baseStats();if(career.badges.includes('recovery')){stats.fatigue=3;stats.injuryRisk=3}if(career.badges.includes('composure'))stats.confidence=70;if(career.badges.includes('fast-start'))stats.energy=4;if(career.badges.includes('scientist'))stats.performance=6;return stats};
const shuffle=<T,>(items:T[])=>{
 const shuffled=[...items];
 for(let index=shuffled.length-1;index>0;index--){
  const swapIndex=Math.floor(Math.random()*(index+1));
  [shuffled[index],shuffled[swapIndex]]=[shuffled[swapIndex],shuffled[index]];
 }
 return shuffled;
};
const sportMatch=(sportTags:string[]|undefined,athlete:Athlete)=>!!sportTags?.some(tag=>tag===athlete.id||athlete.tags.includes(tag));
const pickForAthlete=<T extends {sportTags?:string[]}>(items:T[],athlete:Athlete)=>{
 const specific=items.filter(item=>sportMatch(item.sportTags,athlete));
 const general=items.filter(item=>!item.sportTags?.length);
 const picked=shuffle(specific.length?specific:general.length?general:items)[0];
 if(picked&&'options' in picked){
  const question=picked as T&Question;
  return {...picked,options:shuffle(question.options)} as T;
 }
 return picked;
};
const allOpenQuestions=[...sportOpenQuestions,...openQuestions];
const contextualEventDescription=(event:{description:string;sportTags?:string[]},athlete:Athlete)=>event.sportTags?.length?event.description:`During ${athlete.sport.toLowerCase()} preparation, ${event.description.charAt(0).toLowerCase()}${event.description.slice(1)}`;
const drawHand=(deck:Card[])=>shuffle(deck).slice(0,GAME_RULES.handSize);
const draftOffer=(seenIds:string[],athlete?:Athlete,includeSignature=false)=>{
 const available=cards.filter(card=>!seenIds.includes(card.id));
 const signature=includeSignature&&athlete?synergies.find(s=>s.athleteTags?.some(tag=>athlete.tags.includes(tag))):undefined;
 const featured=signature?[...new globalThis.Map(signature.requiredTags.map(tag=>available.find(card=>card.tags.includes(tag))).filter(Boolean).map(card=>[card!.id,card!])).values()]:[];
 const random=shuffle(available.filter(card=>!featured.some(item=>item.id===card.id))).slice(0,GAME_RULES.draftOfferSize-featured.length);
 return shuffle([...featured,...random]).map(card=>card.id);
};
const clamp=(n:number)=>Math.max(0,Math.min(100,n));
const overall=(athlete:Athlete)=>Math.round(Object.values(athlete.ratings).reduce((n,v)=>n+v,0)/4);
const opponentIntent=(athlete:Athlete,round:number)=>{
 const plans=athlete.tags.includes('power')?[['POWER SURGE','Building strength into explosive power'],['HEAVY CONTACT','Accepting fatigue for a larger performance gain']]:athlete.tags.includes('cardio')||athlete.tags.includes('endurance')?[['ENDURANCE ENGINE','Stacking aerobic work for late-round scoring'],['PACE CONTROL','Protecting Energy while limiting fatigue']]:[['REACTION PRESS','Prioritising speed, agility and technique'],['TECHNICAL EDGE','Chasing a precise skill-based combination']];
 const plan=plans[(round-1)%plans.length];return{name:plan[0],detail:plan[1],projected:`+${16+round}–${24+round}`};
};

function App(){
 const [profile,setProfile]=useState<Profile|null>(()=>persistence.load());
 const [mobileSetupComplete,setMobileSetupComplete]=useState(()=>!window.matchMedia('(max-width: 900px)').matches||sessionStorage.getItem('pe-mobile-ready')==='1');
 const [screen,setScreen]=useState<Screen>(()=>persistence.load()?.tutorialComplete===false?'tutorial':'home');
 const [name,setName]=useState('');
 const [battle,setBattle]=useState<BattleState|null>(null);
 const [selectedAthlete,setSelectedAthlete]=useState<Athlete|null>(null);
 const [draftIds,setDraftIds]=useState<string[]>([]);
 const [draftOfferIds,setDraftOfferIds]=useState<string[]>([]);
 const [draftPickIds,setDraftPickIds]=useState<string[]>([]);
 const [draftSeenIds,setDraftSeenIds]=useState<string[]>([]);
 const [careerBattleId,setCareerBattleId]=useState<string|null>(null);
 const [miniGameNode,setMiniGameNode]=useState<CareerNode|null>(null);
 const [rewardOptions,setRewardOptions]=useState<CoachBadge[]>([]);
 const [report,setReport]=useState<{win:boolean;score:number;ai:number;xp:number;accuracy:number;best:string;topic:string;careerNodeId:string|null}|null>(null);
 useEffect(()=>{
  const fitMobileStage=()=>{
   const root=document.getElementById('root');
   if(!root)return;
   const active=mobileSetupComplete&&innerWidth>innerHeight&&innerHeight<650&&innerWidth<=1100;
   document.body.classList.toggle('mobile-fit-stage',active);
   if(active){const scale=Math.min(1,innerHeight/980);root.style.setProperty('--mobile-fit-scale',String(scale));root.style.width=`${innerWidth/scale}px`;root.style.height=`${innerHeight/scale}px`}
   else{root.style.removeProperty('--mobile-fit-scale');root.style.removeProperty('width');root.style.removeProperty('height')}
  };
  fitMobileStage();window.addEventListener('resize',fitMobileStage);window.addEventListener('orientationchange',fitMobileStage);return()=>{window.removeEventListener('resize',fitMobileStage);window.removeEventListener('orientationchange',fitMobileStage);document.body.classList.remove('mobile-fit-stage')};
 },[mobileSetupComplete,screen,battle?.phase]);
 const saveProfile=(p:Profile)=>{setProfile(p);persistence.save(p)};
 const prepareBattle=(nodeId:string|null=null)=>{setCareerBattleId(nodeId);setSelectedAthlete(null);setDraftIds([]);setDraftOfferIds([]);setDraftPickIds([]);setDraftSeenIds([]);setScreen('select')};
 const chooseAthlete=(athlete:Athlete)=>{const offer=draftOffer([],athlete,true);setSelectedAthlete(athlete);setDraftIds([]);setDraftOfferIds(offer);setDraftPickIds([]);setDraftSeenIds(offer);setScreen('loadout')};
 const toggleDraftPick=(id:string)=>setDraftPickIds(ids=>ids.includes(id)?ids.filter(x=>x!==id):ids.length<GAME_RULES.draftPickSize?[...ids,id]:ids);
 const confirmDraftPicks=()=>{if(draftPickIds.length!==GAME_RULES.draftPickSize)return;const collected=[...draftIds,...draftPickIds];setDraftIds(collected);setDraftPickIds([]);if(collected.length>=GAME_RULES.deckSize){setDraftOfferIds([]);return}const offer=draftOffer(draftSeenIds,selectedAthlete??undefined);setDraftOfferIds(offer);setDraftSeenIds(ids=>[...ids,...offer])};
 const begin=()=>{if(!selectedAthlete||draftIds.length!==GAME_RULES.deckSize)return;const athlete=selectedAthlete;const deck=draftIds.map(id=>cards.find(c=>c.id===id)!).filter(Boolean);const opponent=shuffle(athletes.filter(a=>a.id!==athlete.id))[0];const stats=careerBattleId&&profile?careerStats(profile.career):baseStats();setBattle({round:1,athlete,opponent,deck,stats,ai:baseStats(),hand:drawHand(deck),played:[],usedIds:[],comboIds:[],bestCombo:null,comboFeedback:null,phase:'play',eventIndex:0,question:null,openQuestion:null,openResult:null,answered:0,correct:0,knowledgeScore:0,topicMisses:{},roundMultiplier:1,writtenHint:null,eliminatedOptions:[],log:[careerBattleId?`CAREER NODE — ${careerNodes.find(n=>n.id===careerBattleId)?.title}`:'ROUND 1 — Training phase live']});setScreen('battle')};
 const createProfile=()=>{if(!name.trim())return;saveProfile({name:name.trim().slice(0,20),xp:0,wins:0,battles:0,questionsAnswered:0,questionsCorrect:0,tutorialComplete:false,career:freshCareer(),matchHistory:[]});setScreen('tutorial')};
 const launchMobileGame=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();const orientation=globalThis.screen.orientation as ScreenOrientation&{lock?:(value:'landscape')=>Promise<void>};await orientation.lock?.('landscape')}catch{/* Fullscreen and orientation locking vary by mobile browser. */}sessionStorage.setItem('pe-mobile-ready','1');setMobileSetupComplete(true)};
 const completeTutorial=()=>{if(!profile)return;saveProfile({...profile,tutorialComplete:true,xp:profile.xp+(profile.tutorialComplete?0:25)});setScreen('home')};
 const startCareer=()=>{if(!profile)return;const runNumber=profile.career.active&&!profile.career.champion?profile.career.runNumber:profile.career.runNumber+(profile.career.champion?1:0);saveProfile({...profile,career:{...freshCareer(),active:true,runNumber}});setScreen('career')};
 const completeCareerStop=(node:CareerNode)=>{if(!profile||!node.badgeId)return;const badgeIds=[...new Set([...profile.career.badges,node.badgeId])];saveProfile({...profile,xp:profile.xp+25,career:{...profile.career,active:true,currentNodeId:node.id,completedIds:[...new Set([...profile.career.completedIds,node.id])],badges:badgeIds}})};
 const openMiniGame=(node:CareerNode)=>{setMiniGameNode(node);setScreen('minigame')};
 const completeMiniGame=(node:CareerNode)=>{if(!profile||!node.powerUpId)return;const current=profile.career.powerUps[node.powerUpId]||0;saveProfile({...profile,xp:profile.xp+35,career:{...profile.career,active:true,currentNodeId:node.id,completedIds:[...new Set([...profile.career.completedIds,node.id])],powerUps:{...profile.career.powerUps,[node.powerUpId]:current+1}}});setMiniGameNode(null);setScreen('career')};
 const usePowerUp=(id:PowerUpId)=>{if(!profile||!battle||!careerBattleId||(profile.career.powerUps[id]||0)<1)return;const valid=id==='written-hint'?battle.phase==='open'&&!battle.writtenHint:id==='fifty-fifty'?battle.phase==='question'&&battle.eliminatedOptions.length===0:battle.phase==='play'&&(id!=='double-impact'||battle.roundMultiplier===1);if(!valid)return;const definition=powerUps.find(item=>item.id===id)!;setBattle(b=>{if(!b)return b;const next={...b,stats:{...b.stats},log:[`${definition.name.toUpperCase()} ACTIVATED`,...b.log].slice(0,4)};if(id==='double-impact')next.roundMultiplier=2;if(id==='energy-surge')next.stats.energy+=2;if(id==='recovery-shield'){next.stats.fatigue=clamp(next.stats.fatigue-15);next.stats.injuryRisk=clamp(next.stats.injuryRisk-10)}if(id==='written-hint'&&b.openQuestion)next.writtenHint=b.openQuestion.markPoints[0]?.label||'Link the concept directly to the sporting situation.';if(id==='fifty-fifty'&&b.question)next.eliminatedOptions=shuffle(b.question.options.filter(option=>option!==b.question!.correctAnswer)).slice(0,2);return next});const remaining=(profile.career.powerUps[id]||0)-1;saveProfile({...profile,career:{...profile.career,powerUps:{...profile.career.powerUps,[id]:remaining}}})};
 const playCard=(card:Card)=>setBattle(b=>{
  if(!b||b.phase!=='play'||b.stats.energy<card.cost)return b;
  const played=[...b.played,card],allTags=played.flatMap(c=>c.tags);
  const newly=synergies.filter(s=>!b.comboIds.includes(s.id)&&s.requiredTags.every(t=>allTags.includes(t))&&(!s.athleteTags||s.athleteTags.some(t=>b.athlete.tags.includes(t))));
  const badgeBonus=careerBattleId&&profile?.career.badges.includes('overload')?newly.length*5:0;
  const bonus=newly.reduce((n,s)=>n+s.performanceBonus,0)+badgeBonus;
  const best=newly.reduce<SynergyRule|null>((x,s)=>!x||s.performanceBonus>x.performanceBonus?s:x,b.bestCombo);
  const comboCardPoints=newly.length?played.filter(c=>newly.some(s=>s.requiredTags.some(t=>c.tags.includes(t)))).reduce((sum,c)=>sum+c.performance,0):card.performance;
  const earned=(card.performance+bonus)*b.roundMultiplier;
  const comboFeedback:ComboFeedback|null=newly.length?{name:newly.map(s=>s.name).join(' + '),cardPoints:comboCardPoints,synergyPoints:bonus,totalPoints:(comboCardPoints+bonus)*b.roundMultiplier,multiplier:b.roundMultiplier,explanation:`${newly.map(s=>s.explanation).join(' ')}${badgeBonus?` Overload Expert added ${badgeBonus} extra Performance.`:''}${b.roundMultiplier>1?' Double Impact doubled every point earned this round.':''}`}:null;
  const stats={...b.stats,energy:b.stats.energy-card.cost,performance:b.stats.performance+earned};
  if(card.stat&&card.delta)stats[card.stat]=clamp(stats[card.stat]+card.delta);
  return{...b,stats,played,hand:b.hand.filter(c=>c.id!==card.id),usedIds:[...b.usedIds,card.id],comboIds:[...b.comboIds,...newly.map(s=>s.id)],bestCombo:best,comboFeedback,log:[...(newly.length?[`${newly[0].name} +${(card.performance+bonus)*b.roundMultiplier} PERFORMANCE`]:[`${card.name} +${earned}`]),...b.log].slice(0,4)}
 });
 const launchEvent=()=>setBattle(b=>{if(!b)return b;const unseen=events.filter(event=>!Object.keys(b.topicMisses).includes(`used-event-${event.id}`)&&(sportMatch(event.sportTags,b.athlete)||!event.sportTags?.length));const nextEvent=pickForAthlete(unseen,b.athlete)??pickForAthlete(events,b.athlete)??events[0];return{...b,phase:'event',eventIndex:events.indexOf(nextEvent),topicMisses:{...b.topicMisses,[`used-event-${nextEvent.id}`]:0}}});
 const chooseEvent=(i:number)=>setBattle(b=>{if(!b)return b;const choice=events[b.eventIndex].choices[i],stats={...b.stats};for(const [k,v] of Object.entries(choice.effects)){const delta=k==='performance'?(v??0)*b.roundMultiplier:(v??0);stats[k as keyof Stats]=clamp(stats[k as keyof Stats]+delta)}const multipleChoice=b.round===2,openResponse=b.round===4;const available=questions.filter(q=>!Object.keys(b.topicMisses).includes(`used-${q.id}`));const availableOpen=allOpenQuestions.filter(q=>!Object.keys(b.topicMisses).includes(`used-${q.id}`));const question=multipleChoice?(pickForAthlete(available,b.athlete)??pickForAthlete(questions,b.athlete)??null):null;const openQuestion=openResponse?(pickForAthlete(availableOpen,b.athlete)??pickForAthlete(allOpenQuestions,b.athlete)??null):null;return{...b,stats,phase:multipleChoice?'question':openResponse?'open':'ai',question,openQuestion,openResult:null,topicMisses:{...b.topicMisses,...(question?{[`used-${question.id}`]:0}:{}),...(openQuestion?{[`used-${openQuestion.id}`]:0}:{})},log:[`${choice.quality}: ${choice.feedback}`,...b.log].slice(0,4)}});
 const answer=(option:string)=>setBattle(b=>{if(!b||!b.question)return b;const right=option===b.question.correctAnswer;const edge=(10+(careerBattleId&&profile?.career.badges.includes('focus')?4:0))*b.roundMultiplier;return{...b,phase:'ai',answered:b.answered+1,correct:b.correct+(right?1:0),knowledgeScore:b.knowledgeScore+(right?100:0),stats:{...b.stats,performance:b.stats.performance+(right?edge:0),confidence:clamp(b.stats.confidence+(right?5:-3))},topicMisses:{...b.topicMisses,...(!right?{[b.question.topic]:(b.topicMisses[b.question.topic]||0)+1}:{})},log:[`${right?`KNOWLEDGE EDGE +${edge}`:'MISSED'}: ${b.question.explanation}`,...b.log].slice(0,4)}});
 const submitOpenAnswer=(response:string)=>setBattle(b=>{if(!b||!b.openQuestion)return b;const result=scoreResponse(b.openQuestion,response);const performanceBonus=result.performanceBonus*b.roundMultiplier;return{...b,phase:'open-result',openResult:{...result,performanceBonus},answered:b.answered+1,correct:b.correct+(result.score>=60?1:0),knowledgeScore:b.knowledgeScore+result.score,stats:{...b.stats,performance:b.stats.performance+performanceBonus,confidence:clamp(b.stats.confidence+(result.score>=60?5:-2))},topicMisses:{...b.topicMisses,...(result.score<60?{[b.openQuestion.topic]:(b.topicMisses[b.openQuestion.topic]||0)+1}:{})},log:[`${result.band} ${result.score}%: +${performanceBonus} PERFORMANCE`,...b.log].slice(0,4)}});
 const continueOpenResult=()=>setBattle(b=>b?{...b,phase:'ai'}:b);
 const skipTacticalCall=()=>setBattle(b=>b?{...b,phase:'ai',log:['TACTICAL CALL DECLINED — no bonus risked',...b.log].slice(0,4)}:b);
 const aiTurn=()=>setBattle(b=>{if(!b)return b;const accuracy=Math.random()<.7;const careerStage=careerNodes.find(n=>n.id===careerBattleId)?.stage??0;const careerCurve=careerBattleId?Math.round(careerStage*1.5)-4:0;const aiGain=Math.max(8,9+Math.round(overall(b.opponent)/12)+Math.floor(Math.random()*9)+(accuracy?6:0)+careerCurve);const ai={...b.ai,performance:b.ai.performance+aiGain,confidence:clamp(b.ai.confidence+(accuracy?4:-2)),fatigue:clamp(b.ai.fatigue+7)};if(b.round===GAME_RULES.rounds){const playerFinal=Math.round(b.stats.performance+b.stats.confidence*.22-b.stats.fatigue*.15-b.stats.injuryRisk*.12),aiFinal=Math.round(ai.performance+ai.confidence*.22-ai.fatigue*.15-ai.injuryRisk*.12);finish(b,playerFinal,aiFinal);return b}const next=b.round+1;return{...b,round:next,ai,stats:{...b.stats,energy:GAME_RULES.energyPerRound,fatigue:clamp(b.stats.fatigue+6)},hand:drawHand(b.deck),played:[],comboFeedback:null,phase:'play',question:null,openQuestion:null,openResult:null,roundMultiplier:1,writtenHint:null,eliminatedOptions:[],log:[`ROUND ${next} — Energy restored`,...b.log].slice(0,4)}});
 const finish=(b:BattleState,score:number,ai:number)=>{
  const win=score>ai,xp=50+(win?50:0)+b.correct*12+b.comboIds.length*8;
  const accuracy=b.answered?Math.round(b.knowledgeScore/b.answered):0;
  const best=b.bestCombo?.name||'No synergy discovered';
  const realTopics=Object.entries(b.topicMisses).filter(([k])=>!k.startsWith('used-')).sort((a,c)=>c[1]-a[1]);
  const topic=realTopics[0]?.[0]||'Keep applying knowledge in sporting contexts';
  const p=profile!;
  const match:MatchRecord={id:`${Date.now()}-${b.athlete.id}`,playedAt:new Date().toISOString(),athleteId:b.athlete.id,athleteName:b.athlete.name,sport:b.athlete.sport,win,score,opponentScore:ai,accuracy,questionsAnswered:b.answered,questionsCorrect:b.correct,combos:b.comboIds.length,bestCombo:best,xp,career:!!careerBattleId};
  saveProfile({...p,xp:p.xp+xp,wins:p.wins+(win?1:0),battles:p.battles+1,questionsAnswered:p.questionsAnswered+b.answered,questionsCorrect:p.questionsCorrect+b.correct,matchHistory:[match,...p.matchHistory].slice(0,100)});
  if(win&&careerBattleId){const owned=new Set(p.career.badges);const pool=coachBadges.filter(x=>!owned.has(x.id)&&x.id!=='champion');const choices=shuffle(pool).slice(0,careerBattleId==='championship'?2:3);if(careerBattleId==='championship')choices.unshift(coachBadges.find(x=>x.id==='champion')!);setRewardOptions(choices)}
  setReport({win,score,ai,xp,accuracy,best,topic,careerNodeId:careerBattleId});setTimeout(()=>setScreen('report'),450)
 };
 const claimReward=(badge:CoachBadge)=>{if(!profile||!report?.careerNodeId)return;const nodeId=report.careerNodeId;const champion=nodeId==='championship';saveProfile({...profile,career:{...profile.career,active:true,currentNodeId:nodeId,completedIds:[...new Set([...profile.career.completedIds,nodeId])],badges:[...new Set([...profile.career.badges,badge.id])],careerWins:profile.career.careerWins+1,champion}});setCareerBattleId(null);setScreen('career')};
 if(!profile)return <NameGate name={name} setName={setName} submit={createProfile}/>;
 if(!mobileSetupComplete)return <MobileLaunch start={launchMobileGame}/>;
 if(screen==='tutorial')return <TutorialBattle complete={completeTutorial} exit={profile.tutorialComplete?()=>setScreen('how'):undefined}/>;
 if(screen==='battle'&&battle)return <Battle b={battle} careerNode={careerNodes.find(n=>n.id===careerBattleId)||null} powerUpInventory={profile.career.powerUps} activatePowerUp={usePowerUp} playCard={playCard} launchEvent={launchEvent} chooseEvent={chooseEvent} answer={answer} submitOpenAnswer={submitOpenAnswer} continueOpenResult={continueOpenResult} skipTacticalCall={skipTacticalCall} aiTurn={aiTurn}/>;
 if(screen==='minigame'&&miniGameNode)return <CareerMiniGame node={miniGameNode} complete={completeMiniGame} back={()=>{setMiniGameNode(null);setScreen('career')}}/>;
 if(screen==='report'&&report)return <Report r={report} profile={profile} again={()=>prepareBattle(report.careerNodeId)} home={()=>setScreen(report.careerNodeId?'career':'home')} continueCareer={report.win&&report.careerNodeId?()=>setScreen('reward'):undefined}/>;
 if(screen==='reward'&&report?.careerNodeId)return <RewardScreen node={careerNodes.find(n=>n.id===report.careerNodeId)!} rewards={rewardOptions} choose={claimReward}/>;
 return <Shell profile={profile} screen={screen} setScreen={setScreen}>{screen==='home'?<HomePage profile={profile} begin={()=>prepareBattle(null)} career={()=>setScreen('career')} how={()=>setScreen('how')}/>:screen==='how'?<How replayTutorial={()=>setScreen('tutorial')}/>:screen==='profile'?<ProfileView profile={profile}/>:screen==='career'?<CareerPage profile={profile} start={startCareer} enter={node=>node.type==='battle'||node.type==='championship'?prepareBattle(node.id):node.type==='minigame'?openMiniGame(node):completeCareerStop(node)}/>:screen==='select'?<AthleteSelect choose={chooseAthlete} back={()=>setScreen(careerBattleId?'career':'home')}/>:selectedAthlete?<LoadoutBuilder athlete={selectedAthlete} selectedIds={draftIds} offerIds={draftOfferIds} pickIds={draftPickIds} togglePick={toggleDraftPick} confirmPicks={confirmDraftPicks} start={begin} back={()=>setScreen('select')}/>:null}</Shell>;
}

function NameGate({name,setName,submit}:{name:string;setName:(v:string)=>void;submit:()=>void}){return <main className="gate"><div className="grid-bg"/><div className="brand-mark"><Zap/> PE//BATTLE</div><section className="name-card"><div className="eyebrow">ATHLETE REGISTRATION</div><h1>What should we<br/>call you?</h1><p>Your progress and match stats are saved on this device.</p><form onSubmit={e=>{e.preventDefault();submit()}}><label>PLAYER NAME</label><input autoFocus maxLength={20} value={name} onChange={e=>setName(e.target.value)} placeholder="Enter your name"/><button disabled={!name.trim()}>ENTER THE FACILITY <ArrowRight/></button></form></section></main>}
function MobileLaunch({start}:{start:()=>void}){return <main className="mobile-launch"><div className="mobile-launch-grid"/><section><div className="rotate-demo"><div className="rotate-ring"/><Smartphone/></div><div className="eyebrow">MOBILE GAME SETUP</div><h1>TURN YOUR PHONE<br/><em>SIDEWAYS</em></h1><p>GCSE PE Battle uses a landscape arena so your athlete, opponent, cards and coaching choices remain visible together.</p><div className="orientation-steps"><span><b>1</b> Rotate to landscape</span><i>→</i><span><b>2</b> Tap below for fullscreen</span></div><button onClick={start}><Maximize/> START FULLSCREEN <ArrowRight/></button><small>If fullscreen is unavailable, the game will still fill the browser window.</small></section></main>}
function Shell({profile,screen,setScreen,children}:{profile:Profile;screen:Screen;setScreen:(s:Screen)=>void;children:React.ReactNode}){return <main><header><button className="logo" onClick={()=>setScreen('home')}><Zap/> GCSE PE <b>BATTLE</b></button><nav><button className={screen==='home'?'active':''} onClick={()=>setScreen('home')}>HOME</button><button className={screen==='career'?'active':''} onClick={()=>setScreen('career')}>ROAD TO VICTORY</button><button className={screen==='how'?'active':''} onClick={()=>setScreen('how')}>HOW TO PLAY</button><button className={screen==='profile'?'active':''} onClick={()=>setScreen('profile')}>MY PLAYER</button></nav><div className="player-chip"><span>{profile.name.charAt(0).toUpperCase()}</span><div><b>{profile.name}</b><small>{profile.xp} XP</small></div></div></header>{children}</main>}
function HomePage({profile,begin,career,how}:{profile:Profile;begin:()=>void;career:()=>void;how:()=>void}){return <div className="home"><section className="hero"><div className="hero-copy"><div className="eyebrow"><span/> AQA GCSE PHYSICAL EDUCATION 8582</div><h1>TRAIN.<br/><em>COMPETE.</em><br/>MASTER.</h1><p>Build the athlete. Link the science. Outsmart the opposition.</p><div className="actions"><button className="primary career-cta" onClick={career}><Map/> {profile.career.active?'CONTINUE CAREER':'ROAD TO VICTORY'} <ArrowRight/></button><button className="secondary" onClick={begin}><Zap/> QUICK BATTLE</button><button className="secondary icon-only" aria-label="How to play" onClick={how}><BookOpen/></button></div><div className="mini-stats"><div><b>{profile.battles}</b><span>BATTLES</span></div><div><b>{profile.wins}</b><span>WINS</span></div><div><b>{profile.career.completedIds.length}</b><span>CAREER NODES</span></div></div></div><div className="athlete-showcase"><div className="orbit one"/><div className="orbit two"/><div className="athlete-silhouette"><img src={athletes[0].image} alt="Fictional 100 metre sprinter"/></div><div className="float-card fc1"><small>CAREER RUN</small><b>INTERCONNECTED<br/>PATHS</b><strong>{profile.career.champion?'★':careerNodes.length}</strong></div><div className="float-card fc2"><small>COACHING BADGES</small><b>BUILD YOUR EDGE</b><i>{profile.career.badges.length} UNLOCKED</i></div><div className="scanline"/></div></section><footer>INDEPENDENT EDUCATIONAL REVISION RESOURCE <span>•</span> NOT AFFILIATED WITH OR ENDORSED BY AQA</footer></div>}
function BadgeIcon({badge}:{badge:CoachBadge}){return badge.icon==='recovery'?<HeartPulse/>:badge.icon==='power'?<Dumbbell/>:badge.icon==='mind'?<Brain/>:badge.icon==='energy'?<Flame/>:badge.icon==='science'?<Activity/>:badge.icon==='champion'?<Crown/>:<Target/>}
function NodeIcon({type}:{type:CareerNodeType}){return type==='championship'?<Crown/>:type==='battle'?<Shield/>:type==='recovery'?<HeartPulse/>:type==='minigame'?<Sparkles/>:<Dumbbell/>}
function LegacyCareerPage({profile,start,enter}:{profile:Profile;start:()=>void;enter:(node:CareerNode)=>void}){
 const career=profile.career;
 const current=careerNodes.find(n=>n.id===career.currentNodeId);
 const availableIds=!career.active?[]:current?current.next:['qualifier'];
 const firstFocus=availableIds[0]||career.currentNodeId||'qualifier';
 const [focusId,setFocusId]=useState(firstFocus);
 const focus=careerNodes.find(n=>n.id===focusId)||careerNodes[0];
 const completed=new Set(career.completedIds);
 const owned=coachBadges.filter(b=>career.badges.includes(b.id));
 const connections=careerNodes.flatMap(node=>node.next.map(next=>({from:node.id,to:next})));
 const points:Record<string,[number,number]>={'qualifier':[70,250],'sport-lab':[245,115],'recovery-bay':[245,385],'rival-clash':[420,250],'mindset-centre':[595,115],'altitude-camp':[595,385],'semi-final':[770,250],'championship':[935,250]};
 if(!career.active)return <section className="career-intro"><div className="career-grid-bg"/><div className="intro-crown"><Crown/></div><div className="eyebrow">NEW MODE // CAREER RUN</div><h1>ROAD TO<br/><em>VICTORY</em></h1><p>Choose a route, survive four battles and build a unique coaching setup on the way to the championship.</p><div className="career-rules"><span><Map/><b>BRANCHING ROUTE</b><small>Your decisions shape the run.</small></span><span><Sparkles/><b>BUILD A COACH</b><small>Upgrades change every battle.</small></span><span><Trophy/><b>REACH THE FINAL</b><small>Defeats can be retried.</small></span></div><button className="primary" onClick={start}>BEGIN CAREER RUN <ArrowRight/></button></section>;
 if(career.champion)return <section className="career-victory"><div className="victory-rays"/><div className="victory-crown"><Crown/></div><div className="eyebrow">CAREER RUN {career.runNumber} COMPLETE</div><h1>CHAMPION</h1><p>{profile.name}, you conquered the Road to Victory with {career.badges.length} coaching upgrades.</p><div className="champion-badges">{owned.map(b=><div key={b.id}><BadgeIcon badge={b}/><span>{b.name}</span></div>)}</div><button className="primary" onClick={start}><RotateCcw/> START A NEW RUN</button></section>;
 return <section className="career-page"><div className="career-heading"><div><div className="eyebrow">CAREER RUN {career.runNumber} // ROAD TO VICTORY</div><h2>CHOOSE YOUR NEXT MOVE</h2></div><div className="career-progress"><span>{career.careerWins}<small>BATTLE WINS</small></span><i/><span>{career.badges.length}<small>UPGRADES</small></span><i/><span>{career.completedIds.length}/6<small>STAGES</small></span></div></div><div className="career-layout"><div className="route-map"><div className="map-horizon"/><svg viewBox="0 0 1000 500" preserveAspectRatio="none" aria-hidden="true">{connections.map(link=>{const a=points[link.from],z=points[link.to],done=completed.has(link.from)&&completed.has(link.to),open=completed.has(link.from)&&availableIds.includes(link.to);return <path key={`${link.from}-${link.to}`} className={done?'done':open?'open':''} d={`M ${a[0]} ${a[1]} C ${(a[0]+z[0])/2} ${a[1]}, ${(a[0]+z[0])/2} ${z[1]}, ${z[0]} ${z[1]}`}/>})}</svg>{careerNodes.map(node=>{const [x,y]=points[node.id],done=completed.has(node.id),available=availableIds.includes(node.id),locked=!done&&!available;return <button key={node.id} aria-label={`${node.title}${locked?', locked':''}`} className={`career-node ${node.type} ${done?'complete':''} ${available?'available':''} ${focus.id===node.id?'focused':''}`} style={{left:`${x/10}%`,top:`${y/5}%`}} disabled={locked} onClick={()=>setFocusId(node.id)}><span>{done?<Check/>:locked?<LockKeyhole/>:<NodeIcon type={node.type}/>}</span><b>{node.title}</b><small>{done?'COMPLETE':available?'AVAILABLE':'LOCKED'}</small>{available&&<i/>}</button>})}<div className="map-stage-labels"><span>QUALIFY</span><span>PREPARE</span><span>RIVAL</span><span>DEVELOP</span><span>SEMI-FINAL</span><span>FINAL</span></div></div><aside className="career-detail"><small>{focus.subtitle}</small><div className={`detail-icon ${focus.type}`}><NodeIcon type={focus.type}/></div><h3>{focus.title}</h3><p>{focus.description}</p>{focus.badgeId&&<div className="stop-reward"><span>GUARANTEED UPGRADE</span><b>{coachBadges.find(b=>b.id===focus.badgeId)?.name}</b></div>}<div className="node-status"><span>NODE TYPE <b>{focus.type}</b></span><span>STATUS <b>{completed.has(focus.id)?'COMPLETE':availableIds.includes(focus.id)?'READY':'LOCKED'}</b></span></div>{availableIds.includes(focus.id)&&<button className="primary" onClick={()=>enter(focus)}>{focus.type==='battle'||focus.type==='championship'?'ENTER BATTLE':'COMPLETE TRAINING'} <ArrowRight/></button>}{completed.has(focus.id)&&<div className="complete-stamp"><Check/> COMPLETED</div>}</aside></div><div className="career-inventory"><div><small>ACTIVE COACHING BADGES</small><b>{owned.length?`${owned.length} UPGRADES POWERING YOUR RUN`:'WIN A BATTLE TO CHOOSE YOUR FIRST UPGRADE'}</b></div><div className="badge-row">{owned.map(b=><div className="badge-chip" key={b.id} title={b.description}><BadgeIcon badge={b}/><span><b>{b.name}</b><small>{b.strap}</small></span></div>)}{Array.from({length:Math.max(0,4-owned.length)}).map((_,i)=><div className="badge-chip empty" key={i}><LockKeyhole/><span><b>EMPTY SLOT</b><small>UPGRADE AHEAD</small></span></div>)}</div></div></section>
}
function PowerUpIcon({powerUp}:{powerUp:PowerUpDefinition}){return powerUp.icon==='energy'?<Flame/>:powerUp.icon==='hint'?<Brain/>:powerUp.icon==='scan'?<Target/>:powerUp.icon==='recovery'?<HeartPulse/>:<Zap/>}
function CareerPage({profile,start,enter}:{profile:Profile;start:()=>void;enter:(node:CareerNode)=>void}){
 const career=profile.career;
 const current=careerNodes.find(node=>node.id===career.currentNodeId);
 const availableIds=!career.active?[]:current?current.next:['qualifier'];
 const firstFocus=availableIds[0]||career.currentNodeId||'qualifier';
 const [focusId,setFocusId]=useState(firstFocus);
 const focus=careerNodes.find(node=>node.id===focusId)||careerNodes[0];
 const completed=new Set(career.completedIds);
 const owned=coachBadges.filter(badge=>career.badges.includes(badge.id));
 const ownedPowerUps=powerUps.filter(powerUp=>(career.powerUps[powerUp.id]||0)>0);
 const connections=careerNodes.flatMap(node=>node.next.map(next=>({from:node.id,to:next})));
 const points:Record<string,[number,number]>={
  'qualifier':[55,250],'reaction-arena':[175,72],'sport-lab':[175,250],'recovery-bay':[175,428],
  'knowledge-vault':[315,78],'rival-clash':[315,250],'combo-forge':[315,422],
  'mindset-centre':[455,62],'pressure-match':[455,250],'altitude-camp':[455,438],
  'tactical-scan':[595,92],'recovery-circuit':[595,408],'semi-final':[720,250],
  'final-prep':[835,92],'championship':[945,250]
 };
 const focusPowerUp=focus.powerUpId?powerUps.find(powerUp=>powerUp.id===focus.powerUpId):undefined;
 if(!career.active)return <section className="career-intro"><div className="career-grid-bg"/><div className="intro-crown"><Crown/></div><div className="eyebrow">NEW MODE // CAREER RUN</div><h1>ROAD TO<br/><em>VICTORY</em></h1><p>Choose direct battles or take interconnected detours through training and mini-games. Win consumable power-up cards, build permanent coaching badges and create a different route each run.</p><div className="career-rules"><span><Map/><b>INTERCONNECTED ROUTES</b><small>Paths split, cross and reconnect.</small></span><span><Sparkles/><b>WIN POWER-UPS</b><small>Mini-games award one-use tactical cards.</small></span><span><Trophy/><b>REACH THE FINAL</b><small>Risk extra stops or take the direct route.</small></span></div><button className="primary" onClick={start}>BEGIN CAREER RUN <ArrowRight/></button></section>;
 if(career.champion)return <section className="career-victory"><div className="victory-rays"/><div className="victory-crown"><Crown/></div><div className="eyebrow">CAREER RUN {career.runNumber} COMPLETE</div><h1>CHAMPION</h1><p>{profile.name}, you conquered the Road to Victory after clearing {career.completedIds.length} nodes, with {career.badges.length} permanent coaching upgrades.</p><div className="champion-badges">{owned.map(badge=><div key={badge.id}><BadgeIcon badge={badge}/><span>{badge.name}</span></div>)}</div><button className="primary" onClick={start}><RotateCcw/> START A NEW RUN</button></section>;
 return <section className="career-page">
  <div className="career-heading"><div><div className="eyebrow">CAREER RUN {career.runNumber} // ROAD TO VICTORY</div><h2>CHOOSE YOUR NEXT MOVE</h2></div><div className="career-progress"><span>{career.careerWins}<small>BATTLE WINS</small></span><i/><span>{career.badges.length}<small>BADGES</small></span><i/><span>{career.completedIds.length}<small>NODES CLEARED</small></span></div></div>
  <div className="career-layout"><div className="route-map expanded"><div className="map-horizon"/><svg viewBox="0 0 1000 500" preserveAspectRatio="none" aria-hidden="true">{connections.map(link=>{const from=points[link.from],to=points[link.to],done=completed.has(link.from)&&completed.has(link.to),open=completed.has(link.from)&&availableIds.includes(link.to);return <path key={`${link.from}-${link.to}`} className={done?'done':open?'open':''} d={`M ${from[0]} ${from[1]} C ${(from[0]+to[0])/2} ${from[1]}, ${(from[0]+to[0])/2} ${to[1]}, ${to[0]} ${to[1]}`}/>})}</svg>
   {careerNodes.map(node=>{const [x,y]=points[node.id],done=completed.has(node.id),available=availableIds.includes(node.id),locked=!done&&!available;return <button key={node.id} aria-label={`${node.title}${locked?', locked':''}`} className={`career-node ${node.type} ${done?'complete':''} ${available?'available':''} ${focus.id===node.id?'focused':''}`} style={{left:`${x/10}%`,top:`${y/5}%`}} disabled={locked} onClick={()=>setFocusId(node.id)}><span>{done?<Check/>:locked?<LockKeyhole/>:<NodeIcon type={node.type}/>}</span><b>{node.title}</b><small>{done?'COMPLETE':available?'AVAILABLE':'LOCKED'}</small>{available&&<i/>}</button>})}
   <div className="map-stage-labels expanded-labels"><span>QUALIFY</span><span>DETOUR 1</span><span>RECONNECT</span><span>DEVELOP</span><span>POWER-UP</span><span>SEMI-FINAL</span><span>FINAL PREP</span><span>FINAL</span></div>
  </div><aside className="career-detail"><small>{focus.subtitle}</small><div className={`detail-icon ${focus.type}`}><NodeIcon type={focus.type}/></div><h3>{focus.title}</h3><p>{focus.description}</p>{focus.badgeId&&<div className="stop-reward"><span>PERMANENT RUN UPGRADE</span><b>{coachBadges.find(badge=>badge.id===focus.badgeId)?.name}</b></div>}{focusPowerUp&&<div className="stop-reward power-prize"><span>MINI-GAME PRIZE</span><b>{focusPowerUp.name} • {focusPowerUp.strap}</b></div>}<div className="node-status"><span>NODE TYPE <b>{focus.type==='minigame'?'MINI-GAME':focus.type}</b></span><span>STATUS <b>{completed.has(focus.id)?'COMPLETE':availableIds.includes(focus.id)?'READY':'LOCKED'}</b></span></div>{availableIds.includes(focus.id)&&<button className="primary" onClick={()=>enter(focus)}>{focus.type==='battle'||focus.type==='championship'?'ENTER BATTLE':focus.type==='minigame'?'PLAY CHALLENGE':'COMPLETE TRAINING'} <ArrowRight/></button>}{completed.has(focus.id)&&<div className="complete-stamp"><Check/> COMPLETED</div>}</aside></div>
  <div className="career-inventory"><div><small>ACTIVE COACHING BADGES</small><b>{owned.length?`${owned.length} PERMANENT UPGRADES POWERING THIS RUN`:'WIN A BATTLE OR VISIT A TRAINING STOP'}</b></div><div className="badge-row">{owned.map(badge=><div className="badge-chip" key={badge.id} title={badge.description}><BadgeIcon badge={badge}/><span><b>{badge.name}</b><small>{badge.strap}</small></span></div>)}{Array.from({length:Math.max(0,4-owned.length)}).map((_,index)=><div className="badge-chip empty" key={index}><LockKeyhole/><span><b>EMPTY SLOT</b><small>UPGRADE AHEAD</small></span></div>)}</div></div>
  <div className="powerup-inventory"><div><small>POWER-UP CARD DECK</small><b>{ownedPowerUps.length?'CONSUMABLES READY FOR A CAREER BATTLE':'TAKE A MINI-GAME DETOUR TO WIN YOUR FIRST CARD'}</b></div><div className="powerup-row">{powerUps.map(powerUp=><div className={`powerup-chip ${(career.powerUps[powerUp.id]||0)>0?'owned':'empty'}`} key={powerUp.id}><PowerUpIcon powerUp={powerUp}/><span><b>{powerUp.name}</b><small>{powerUp.strap}</small></span><strong>×{career.powerUps[powerUp.id]||0}</strong></div>)}</div></div>
 </section>;
}
function CareerMiniGame({node,complete,back}:{node:CareerNode;complete:(node:CareerNode)=>void;back:()=>void}){
 const reward=powerUps.find(powerUp=>powerUp.id===node.powerUpId)!;
 const [targets,setTargets]=useState(()=>shuffle([1,2,3,4,5,6]));
 const [nextTarget,setNextTarget]=useState(1);
 const [startedAt,setStartedAt]=useState<number|null>(null);
 const [misses,setMisses]=useState(0);
 const [outcome,setOutcome]=useState<{won:boolean;detail:string}|null>(null);
 const comboChallenges=[
  {prompt:'POWER',context:'Which training method develops explosive strength × speed?',answer:'PLYOMETRIC TRAINING',options:['CONTINUOUS TRAINING','PLYOMETRIC TRAINING','SPORTS MASSAGE']},
  {prompt:'CARDIOVASCULAR ENDURANCE',context:'Which method most directly develops sustained aerobic work?',answer:'CONTINUOUS TRAINING',options:['WEIGHT TRAINING','FLEXIBILITY TRAINING','CONTINUOUS TRAINING']},
  {prompt:'STRENGTH',context:'Which method uses resistance to increase maximum force?',answer:'WEIGHT TRAINING',options:['WEIGHT TRAINING','FARTLEK TRAINING','MENTAL REHEARSAL']}
 ];
 const [comboRound,setComboRound]=useState(0);
 const [comboScore,setComboScore]=useState(0);
 const [selected,setSelected]=useState<string|null>(null);
 const restart=()=>{setTargets(shuffle([1,2,3,4,5,6]));setNextTarget(1);setStartedAt(null);setMisses(0);setOutcome(null);setComboRound(0);setComboScore(0);setSelected(null)};
 const hitTarget=(target:number)=>{if(outcome)return;if(target!==nextTarget){setMisses(value=>value+1);return}const start=startedAt??Date.now();if(!startedAt)setStartedAt(start);if(target===6){const elapsed=Date.now()-start+misses*1000;setOutcome({won:elapsed<=16000,detail:`${(elapsed/1000).toFixed(1)} seconds including ${misses} error ${misses===1?'penalty':'penalties'}`})}else setNextTarget(target+1)};
 const advanceCombo=()=>{if(!selected)return;const score=comboScore+(selected===comboChallenges[comboRound].answer?1:0);if(comboRound===comboChallenges.length-1)setOutcome({won:score>=2,detail:`${score} of ${comboChallenges.length} GCSE PE links matched`});else{setComboScore(score);setComboRound(round=>round+1);setSelected(null)}};
 const challenge=comboChallenges[comboRound];
 return <main className="minigame-screen"><div className="career-grid-bg"/><button className="text-back minigame-back" onClick={back}><ArrowLeft/> RETURN TO ROUTE</button><section className="minigame-card"><div className="minigame-heading"><span><Sparkles/></span><div><small>{node.subtitle} // POWER-UP DETOUR</small><h1>{node.title}</h1><p>{node.description}</p></div><div className="prize-card"><PowerUpIcon powerUp={reward}/><span><small>PRIZE</small><b>{reward.name}</b><em>{reward.strap}</em></span></div></div>
  {outcome?<div className={`minigame-result ${outcome.won?'won':'lost'}`}><div>{outcome.won?<Trophy/>:<RotateCcw/>}</div><small>{outcome.won?'CHALLENGE COMPLETE':'NOT QUITE'}</small><h2>{outcome.won?'POWER-UP UNLOCKED':'RUN IT AGAIN'}</h2><p>{outcome.detail}</p><div className="actions">{outcome.won?<button className="primary" onClick={()=>complete(node)}>CLAIM {reward.name.toUpperCase()} <ArrowRight/></button>:<button className="primary" onClick={restart}><RotateCcw/> RETRY CHALLENGE</button>}<button className="secondary" onClick={back}>RETURN TO MAP</button></div></div>
  :node.miniGame==='reaction'?<div className="reaction-game"><div className="minigame-instruction"><Target/><span><b>TAP 1 → 6 IN ORDER</b><small>Wrong targets add a one-second penalty. Finish inside 16 seconds.</small></span><strong>NEXT {nextTarget}</strong></div><div className="reaction-grid">{targets.map(target=><button key={target} className={target<nextTarget?'hit':target===nextTarget?'next':''} onClick={()=>hitTarget(target)} disabled={target<nextTarget}><span>{target<nextTarget?<Check/>:target}</span></button>)}</div><div className="challenge-meter"><span>PROGRESS</span><div><i style={{width:`${((nextTarget-1)/6)*100}%`}}/></div><b>{nextTarget-1}/6</b><em>{misses} ERRORS</em></div></div>
  :<div className="combo-game"><div className="combo-round"><span>LINK {comboRound+1} / {comboChallenges.length}</span><div>{comboChallenges.map((_,index)=><i key={index} className={index<comboRound?'complete':index===comboRound?'current':''}/>)}</div><strong>{comboScore} CORRECT</strong></div><div className="concept-signal"><small>GCSE PE CONCEPT</small><h2>{challenge.prompt}</h2><p>{challenge.context}</p></div><div className="combo-options">{challenge.options.map(option=>{const chosen=selected===option,correct=selected&&option===challenge.answer,wrong=chosen&&option!==challenge.answer;return <button className={correct?'correct':wrong?'wrong':''} disabled={!!selected} key={option} onClick={()=>setSelected(option)}><span>{correct?<Check/>:wrong?'×':'+'}</span>{option}</button>})}</div>{selected&&<div className={`link-feedback ${selected===challenge.answer?'correct':'wrong'}`}><b>{selected===challenge.answer?'STRONG LINK':'LINK BROKEN'}</b><span>{selected===challenge.answer?'That pairing is scientifically valid.':'Review the component definition and choose its most specific partner next time.'}</span><button className="primary" onClick={advanceCombo}>{comboRound===comboChallenges.length-1?'CALCULATE RESULT':'NEXT LINK'} <ArrowRight/></button></div>}</div>}
 </section></main>;
}
function RewardScreen({node,rewards,choose}:{node:CareerNode;rewards:CoachBadge[];choose:(badge:CoachBadge)=>void}){return <main className="reward-screen"><div className="reward-particles">{Array.from({length:18}).map((_,i)=><i key={i} style={{'--i':i,left:`${(i*47)%100}%`} as React.CSSProperties}/>)}</div><div className="reward-heading"><div className="reward-win"><Trophy/></div><div className="eyebrow">{node.title.toUpperCase()} // VICTORY REWARD</div><h1>CHOOSE YOUR EDGE</h1><p>Select one coaching badge. Its effect lasts for the rest of this career run.</p></div><div className="reward-cards">{rewards.map((badge,i)=><button key={badge.id} style={{'--delay':`${i*.12}s`} as React.CSSProperties} onClick={()=>choose(badge)}><small>{badge.strap}</small><div><BadgeIcon badge={badge}/></div><h2>{badge.name}</h2><p>{badge.description}</p><span>TAKE BADGE <ArrowRight/></span></button>)}</div><small className="reward-note">CHOOSE CAREFULLY — YOUR ROUTE AND UPGRADES CREATE A DIFFERENT BUILD EACH RUN</small></main>}
function AthleteSelect({choose,back}:{choose:(athlete:Athlete)=>void;back:()=>void}){return <section className="prematch"><div className="prematch-top"><button className="text-back" onClick={back}><ArrowLeft/> BACK</button><div><div className="eyebrow">PRE-MATCH // STEP 1 OF 2</div><h2>CHOOSE YOUR ATHLETE</h2><p>Every athlete rewards a different GCSE PE strategy.</p></div><div className="selection-progress"><i className="on"/><i/></div></div><div className="athlete-grid realistic">{athletes.map(a=>{const signature=synergies.filter(s=>s.athleteTags?.some(t=>a.tags.includes(t))).slice(0,2);return <button className="athlete-choice" key={a.id} onClick={()=>choose(a)} style={{'--athlete-accent':a.accent} as React.CSSProperties}><div className="choice-art"><img src={a.image} alt={`Fictional ${a.sport}`}/><div className="overall"><strong>{overall(a)}</strong><small>OVR</small></div><span>{a.icon}</span></div><div className="choice-info"><small>{a.role}</small><h3>{a.sport}</h3><p>{a.name}</p><div className="rating-row">{Object.entries(a.ratings).map(([name,value])=><div key={name}><b>{value}</b><span>{name.slice(0,3)}</span></div>)}</div><div className="tag-row">{a.tags.slice(0,3).map(t=><i key={t}>{t}</i>)}</div></div><footer><span>{signature[0]?.name||'ADAPTIVE BUILD'}</span><ArrowRight/></footer></button>})}</div><div className="prematch-tip"><Target/><span><b>STRATEGY MATTERS</b> Your athlete determines which card combinations earn the largest performance bonuses.</span></div></section>}
function LegacyLoadoutBuilder({athlete,selectedIds,offerIds,pickIds,togglePick,confirmPicks,start,back}:{athlete:Athlete;selectedIds:string[];offerIds:string[];pickIds:string[];togglePick:(id:string)=>void;confirmPicks:()=>void;start:()=>void;back:()=>void}){
 const selectedCards=useMemo(()=>selectedIds.map(id=>cards.find(c=>c.id===id)!).filter(Boolean),[selectedIds]);
 const offerCards=offerIds.map(id=>cards.find(c=>c.id===id)!).filter(Boolean);
 const selectedTags=selectedCards.flatMap(c=>c.tags);
 const readySynergies=synergies.filter(s=>(!s.athleteTags||s.athleteTags.some(t=>athlete.tags.includes(t)))&&s.requiredTags.every(t=>selectedTags.includes(t))).sort((a,b)=>b.performanceBonus-a.performanceBonus);
 const complete=selectedIds.length===GAME_RULES.deckSize;
 const draftRound=Math.min(Math.floor(selectedIds.length/GAME_RULES.draftPickSize)+1,GAME_RULES.draftRounds);
 return <section className="prematch loadout draft-mode"><div className="prematch-top"><button className="text-back" onClick={back}><ArrowLeft/> ATHLETES</button><div><div className="eyebrow">PRE-MATCH // STEP 2 OF 2</div><h2>DRAFT YOUR TRAINING PLAN</h2><p>Five random cards. Choose two. Your GCSE PE knowledge decides which combinations make the plan.</p></div><div className="selection-progress"><i className="on"/><i className="on"/></div></div><div className="loadout-layout"><aside className="loadout-athlete" style={{'--athlete-accent':athlete.accent} as React.CSSProperties}><div className="loadout-portrait"><img src={athlete.image} alt={`Fictional ${athlete.sport}`}/><span>{overall(athlete)} OVR</span></div><div className="loadout-identity"><span>{athlete.icon}</span><div><small>YOUR ATHLETE</small><b>{athlete.sport}</b><p>{athlete.name}</p></div></div><div className="deck-count"><strong>{selectedIds.length}</strong><span>/ {GAME_RULES.deckSize} DRAFTED</span></div><div className="curve"><small>ENERGY CURVE</small><div><span>1 ENERGY <b>{selectedCards.filter(c=>c.cost===1).length}</b></span><span>2 ENERGY <b>{selectedCards.filter(c=>c.cost===2).length}</b></span></div></div><div className="synergy-list"><small>COMBOS DISCOVERED</small>{readySynergies.length?<>{readySynergies.slice(0,4).map(s=><div key={s.id}><Zap/><span><b>{s.name}</b><small>+{s.performanceBonus} PERFORMANCE</small></span></div>)}{readySynergies.length>4&&<p>+{readySynergies.length-4} more available</p>}</>:<p>No combination yet. Look for related components, methods and GCSE concepts.</p>}</div><button className="primary launch-battle" disabled={!complete} onClick={start}><Zap/> LOCK PLAN &amp; BATTLE <ArrowRight/></button></aside><div className="draft-pool"><div className="draft-head"><div><b>{complete?'PLAN COMPLETE':`DRAFT ROUND ${draftRound} OF ${GAME_RULES.draftRounds}`}</b><span>{complete?'Your ten-card plan is ready for battle.':`Select exactly ${GAME_RULES.draftPickSize} of these ${GAME_RULES.draftOfferSize} cards`}</span></div><div className="draft-pick-counter"><strong>{complete?GAME_RULES.deckSize:pickIds.length}</strong><span>/ {complete?GAME_RULES.deckSize:GAME_RULES.draftPickSize} {complete?'CARDS':'PICKS'}</span></div></div>{complete?<div className="draft-complete"><div className="complete-mark"><Check/></div><h3>TACTICAL PLAN LOCKED</h3><p>You built this deck through five decisions—not an automatic recommendation.</p><div className="collected-strip">{selectedCards.map(card=><MiniCard key={card.id} card={card}/>)}</div><button className="primary" onClick={start}><Zap/> ENTER BATTLE <ArrowRight/></button></div>:<><div className="offer-grid">{offerCards.map(card=>{const picked=pickIds.includes(card.id);return <button key={card.id} className={`offer-card ${card.type} ${picked?'picked':''}`} onClick={()=>togglePick(card.id)} disabled={!picked&&pickIds.length>=GAME_RULES.draftPickSize}><CardArtwork card={card}/><div className="offer-card-top"><small>{card.type}</small><span>{card.cost}<Flame/></span></div><h3>{card.name}</h3><p>{card.effect}</p><div className="offer-tags">{card.tags.slice(0,2).map(tag=><i key={tag}>{tag}</i>)}</div><footer><b>+{card.performance} PERF</b><span>{picked?<><Check/> PICKED</>:<>SELECT</>}</span></footer></button>})}</div><div className="draft-decision"><div><Brain/><span><b>READ THE CARDS</b> Which pair matches your athlete, Energy budget or a GCSE PE combination?</span></div><button className="primary" disabled={pickIds.length!==GAME_RULES.draftPickSize} onClick={confirmPicks}>CONFIRM {GAME_RULES.draftPickSize} PICKS <ArrowRight/></button></div></>}</div></div></section>
}

function LoadoutBuilder({athlete,selectedIds,offerIds,pickIds,togglePick,confirmPicks,start,back}:{athlete:Athlete;selectedIds:string[];offerIds:string[];pickIds:string[];togglePick:(id:string)=>void;confirmPicks:()=>void;start:()=>void;back:()=>void}){
 const selectedCards=useMemo(()=>selectedIds.map(id=>cards.find(c=>c.id===id)!).filter(Boolean),[selectedIds]);
 const offerCards=offerIds.map(id=>cards.find(c=>c.id===id)!).filter(Boolean);
 const athleteSynergies=synergies.filter(s=>!s.athleteTags||s.athleteTags.some(t=>athlete.tags.includes(t)));
 const signatureSynergies=athleteSynergies.filter(s=>s.athleteTags?.length);
 const selectedTags=selectedCards.flatMap(c=>c.tags);
 const readySynergies=athleteSynergies.filter(s=>s.requiredTags.every(t=>selectedTags.includes(t))).sort((a,b)=>b.performanceBonus-a.performanceBonus);
 const complete=selectedIds.length===GAME_RULES.deckSize;
 const draftRound=Math.min(Math.floor(selectedIds.length/GAME_RULES.draftPickSize)+1,GAME_RULES.draftRounds);
 const partnerFor=(card:Card)=>{
  const links=athleteSynergies.filter(s=>s.requiredTags.some(t=>card.tags.includes(t))).sort((a,b)=>Number(!!b.athleteTags)-Number(!!a.athleteTags)||b.performanceBonus-a.performanceBonus);
  for(const link of links){
   const completes=(other:Card)=>other.id!==card.id&&link.requiredTags.every(tag=>card.tags.includes(tag)||other.tags.includes(tag));
   const available=offerCards.find(completes);
   const owned=selectedCards.find(completes);
   const suggested=cards.find(completes);
   if(available||owned||suggested)return{link,partner:available||owned||suggested!,state:available?'available':owned?'owned':'future'} as const;
  }
  return null;
 };
 const pairNames=(rule:SynergyRule)=>rule.requiredTags.map(tag=>cards.find(card=>card.tags.includes(tag))?.name||tag).join(' + ');
 return <section className="prematch loadout draft-mode" style={{'--athlete-accent':athlete.accent} as React.CSSProperties}>
  <div className="prematch-top">
   <button className="text-back" onClick={back}><ArrowLeft/> ATHLETES</button>
   <div><div className="eyebrow">PRE-MATCH // STEP 2 OF 2</div><h2>DRAFT YOUR TRAINING PLAN</h2><p>Your opening five include a signature sport pair plus three random cards. Choose two using the pairing clues.</p></div>
   <div className="selection-progress"><i className="on"/><i className="on"/></div>
  </div>
  <div className="loadout-layout">
   <aside className="loadout-athlete" style={{'--athlete-accent':athlete.accent} as React.CSSProperties}>
    <div className="loadout-portrait"><img src={athlete.image} alt={`Fictional ${athlete.sport}`}/><span>{overall(athlete)} OVR</span></div>
    <div className="loadout-identity"><span>{athlete.icon}</span><div><small>YOUR ATHLETE</small><b>{athlete.sport}</b><p>{athlete.name}</p></div></div>
    <div className="deck-count"><strong>{selectedIds.length}</strong><span>/ {GAME_RULES.deckSize} DRAFTED</span></div>
    <div className="curve"><small>ENERGY CURVE</small><div><span>1 ENERGY <b>{selectedCards.filter(c=>c.cost===1).length}</b></span><span>2 ENERGY <b>{selectedCards.filter(c=>c.cost===2).length}</b></span></div></div>
    <div className="synergy-list"><small>COMBOS DISCOVERED</small>{readySynergies.length?<>{readySynergies.slice(0,4).map(s=><div key={s.id}><Zap/><span><b>{s.name}</b><small>+{s.performanceBonus} PERFORMANCE</small></span></div>)}{readySynergies.length>4&&<p>+{readySynergies.length-4} more available</p>}</>:<p>No combination yet. Follow the pairing clues to link components, methods and muscles.</p>}</div>
    <button className="primary launch-battle" disabled={!complete} onClick={start}><Zap/> LOCK PLAN &amp; BATTLE <ArrowRight/></button>
   </aside>
   <div className="draft-pool">
    <div className="draft-head"><div><b>{complete?'PLAN COMPLETE':`DRAFT ROUND ${draftRound} OF ${GAME_RULES.draftRounds}`}</b><span>{complete?'Your ten-card plan is ready for battle.':`Select exactly ${GAME_RULES.draftPickSize} of these ${GAME_RULES.draftOfferSize} cards`}</span></div><div className="draft-pick-counter"><strong>{complete?GAME_RULES.deckSize:pickIds.length}</strong><span>/ {complete?GAME_RULES.deckSize:GAME_RULES.draftPickSize} {complete?'CARDS':'PICKS'}</span></div></div>
    {!complete&&<div className="sport-combo-brief"><Target/><div><small>{athlete.sport.toUpperCase()} // SIGNATURE COMBINATIONS</small><b>{signatureSynergies.slice(0,3).map(s=>s.name).join('  •  ')}</b><span>{signatureSynergies.slice(0,2).map(pairNames).join('  |  ')}. Battle scenarios and questions will also use {athlete.sport} contexts.</span></div></div>}
    {complete?<div className="draft-complete"><div className="complete-mark"><Check/></div><h3>TACTICAL PLAN LOCKED</h3><p>You built this deck through five decisions—not an automatic recommendation.</p><div className="collected-strip">{selectedCards.map(card=><MiniCard key={card.id} card={card}/>)}</div><button className="primary" onClick={start}><Zap/> ENTER BATTLE <ArrowRight/></button></div>:<>
     <div className="offer-grid">{offerCards.map(card=>{
      const picked=pickIds.includes(card.id),hint=partnerFor(card);
      return <button key={card.id} className={`offer-card ${card.type} ${picked?'picked':''} ${hint?.state==='available'?'combo-ready':hint?.state==='owned'?'combo-owned':''} ${hint?.link.athleteTags?'sport-fit':''}`} onClick={()=>togglePick(card.id)} disabled={!picked&&pickIds.length>=GAME_RULES.draftPickSize}>
       <CardArtwork card={card}/>
       <div className={`pairing-hint ${hint?.state||''}`}>{hint&&<><Zap/><span><small>{hint.state==='available'?'PAIR AVAILABLE':hint.state==='owned'?'PAIR IN YOUR PLAN':'LOOK FOR THIS PARTNER'}</small><b>{hint.partner.name}</b><em>{hint.link.name} +{hint.link.performanceBonus}</em></span></>}</div>
       <div className="offer-card-top"><small>{card.type}</small><span>{card.cost}<Flame/></span></div><h3>{card.name}</h3><p>{card.effect}</p><div className="offer-tags">{card.tags.slice(0,2).map(tag=><i key={tag}>{tag}</i>)}</div>
       <footer><b>+{card.performance} PERF</b><span>{picked?<><Check/> PICKED</>:<>SELECT</>}</span></footer>
      </button>
     })}</div>
     <div className="draft-decision"><div><Brain/><span><b>READ THE LINKS</b> Glowing cards have a useful partner in this offer. Pairing them activates the named GCSE PE combination.</span></div><button className="primary" disabled={pickIds.length!==GAME_RULES.draftPickSize} onClick={confirmPicks}>CONFIRM {GAME_RULES.draftPickSize} PICKS <ArrowRight/></button></div>
    </>}
   </div>
  </div>
 </section>;
}

function TutorialBattle({complete,exit}:{complete:()=>void;exit?:()=>void}){
 const player=athletes.find(a=>a.id===TUTORIAL_RULES.playerAthleteId)!;
 const opponent=athletes.find(a=>a.id===TUTORIAL_RULES.opponentAthleteId)!;
 const tutorialCards=TUTORIAL_RULES.cardIds.map(id=>cards.find(c=>c.id===id)!).filter(Boolean);
 const tutorialSynergy=synergies.find(s=>s.id===TUTORIAL_RULES.synergyId)!;
 const [step,setStep]=useState(0);
 const [drafted,setDrafted]=useState<string[]>([]);
 const [selected,setSelected]=useState<string[]>([]);
 const [wrong,setWrong]=useState('');
 const comboReady=TUTORIAL_RULES.requiredCardIds.every(id=>selected.includes(id));
 const basePerformance=selected.reduce((sum,id)=>sum+(cards.find(c=>c.id===id)?.performance||0),0);
 const playerPerformance=basePerformance+(comboReady?tutorialSynergy.performanceBonus:0)+(step>=6?5:0);
 const toggleTutorialDraft=(card:Card)=>{setWrong('');setDrafted(ids=>ids.includes(card.id)?ids.filter(id=>id!==card.id):ids.length<GAME_RULES.draftPickSize?[...ids,card.id]:ids)};
 const confirmTutorialDraft=()=>{if(drafted.length!==GAME_RULES.draftPickSize)return;if(!TUTORIAL_RULES.requiredCardIds.every(id=>drafted.includes(id))){setWrong('That pair does not create Repeat Speed. Use GCSE PE knowledge: which training method develops speed through work and recovery periods?');return}setWrong('');setStep(2)};
 const playTutorialCard=(card:Card)=>{const required=TUTORIAL_RULES.requiredCardIds[step-2];if(card.id!==required)return;setSelected(ids=>[...ids,card.id]);setStep(s=>s+1)};
 const playerStats={...baseStats(),performance:playerPerformance,confidence:step>=6?74:60};
 const opponentStats={...baseStats(),performance:step>=6?TUTORIAL_RULES.opponentPerformance:0};
 return <main className="battle tutorial-battle" style={{'--accent':player.accent} as React.CSSProperties}><div className="battle-top"><div className="battle-brand"><Zap/> PE//BATTLE <span>// GUIDED MATCH</span></div><div className="tutorial-progress"><small>TUTORIAL</small>{[1,2,3,4,5].map(n=><i key={n} className={step>=n?'on':''}>{n}</i>)}</div>{exit?<button className="tutorial-exit" onClick={exit}>EXIT TUTORIAL</button>:<div className="opponent-label">FIRST MATCH // NO PRESSURE</div>}</div><section className="arena tutorial-arena"><AthletePanel athlete={player} stats={playerStats}/><div className="centre-stage">{step===0?<Modal title="WELCOME, COACH" tag="YOUR FIRST BATTLE" icon={<Target/>}><p>You control the athlete on the <b>left</b>. First you will draft a useful pair from five random cards, then play the combination.</p><button className="event-button" onClick={()=>setStep(1)}>START TUTORIAL <ArrowRight/></button></Modal>:step===1?<><div className="phase-label">GUIDED DRAFT</div><div className="tutorial-callout"><span>STEP 1 OF 5</span><b>CHOOSE TWO FROM FIVE</b><p>Find Speed and the training method that uses work and recovery periods. Together they create Repeat Speed.</p></div><div className="combo-space tutorial-draft-space"><Target/><b>{drafted.length} / {GAME_RULES.draftPickSize} PICKS</b><span>Your choice creates the plan—nothing is preselected.</span></div>{wrong&&<div className="tutorial-correction">{wrong}</div>}<button className="event-button" disabled={drafted.length!==GAME_RULES.draftPickSize} onClick={confirmTutorialDraft}>CONFIRM PAIR <ArrowRight/></button></>:step<=4?<><div className="phase-label">GUIDED BUILD PHASE</div><div className="tutorial-callout"><span>STEP {step} OF 5</span><b>{step===2?'PLAY SPEED':step===3?'ADD INTERVAL TRAINING':'COMBINATION READY'}</b><p>{step===2?'Your drafted cards form the battle hand. Speed costs 1 of your 3 Energy.':step===3?'Interval Training costs 2, taking your total to 3 Energy.':'These GCSE PE concepts are linked, so Repeat Speed adds a bonus.'}</p></div><div className={`combo-space ${comboReady?'tutorial-combo':''}`}>{selected.length?<div className="played-row">{selected.map(id=><MiniCard key={id} card={cards.find(c=>c.id===id)!}/>)}</div>:<><Target/><b>YOUR MOVE</b><span>Select the glowing Speed card below</span></>}{comboReady&&<div className="tutorial-synergy"><Zap/> {tutorialSynergy.name} +{tutorialSynergy.performanceBonus}</div>}</div>{step===4&&<button className="event-button" onClick={()=>setStep(5)}>LOCK IN &amp; RESPOND <ArrowRight/></button>}</>:step===5?<Modal title="COMPETITION ANXIETY" tag="RESPOND PHASE" icon={<Brain/>}><p>Your performer is over-aroused before the race. Choose the best coaching response.</p><div className="choices">{['Use controlled breathing','Increase the pressure','Ignore the athlete'].map((choice,i)=><button key={choice} onClick={()=>i===0?(setWrong(''),setStep(6)):setWrong('Not quite — that could increase anxiety. Try the response that lowers arousal.')}><span>{String.fromCharCode(65+i)}</span>{choice}<ArrowRight/></button>)}</div>{wrong&&<div className="tutorial-correction">{wrong}</div>}</Modal>:<Modal title="PRACTICE ROUND WON" tag="TUTORIAL COMPLETE" icon={<Trophy/>}><div className="tutorial-score"><span>YOUR SCORE <b>{playerPerformance}</b></span><i>—</i><span>CPU SCORE <b>{TUTORIAL_RULES.opponentPerformance}</b></span></div><p>You drafted a purposeful pair, built a combination and applied GCSE PE knowledge to win.</p><button className="event-button" onClick={complete}>CLAIM 25 XP &amp; CONTINUE <ArrowRight/></button></Modal>}</div><AthletePanel athlete={opponent} stats={opponentStats} opponent/></section>{step===1&&<section className="hand-area tutorial-hand tutorial-draft-hand"><div className="hand-head"><div><small>DRAFT OFFER // FIVE RANDOM CARDS</small><b>Select Speed and the matching training method</b></div><div className="tutorial-energy"><Brain/> PICKS <strong>{drafted.length}</strong><span>/ {GAME_RULES.draftPickSize}</span></div></div><div className="hand">{tutorialCards.map(card=>{const isSelected=drafted.includes(card.id);return <div className={`tutorial-card-wrap ${isSelected?'selected':''}`} key={card.id}><CardView card={card} disabled={!isSelected&&drafted.length>=GAME_RULES.draftPickSize} play={()=>toggleTutorialDraft(card)}/>{isSelected&&<span className="click-me">PICKED</span>}</div>})}</div></section>}{step>=2&&step<=4&&<section className="hand-area tutorial-hand"><div className="hand-head"><div><small>YOUR DRAFTED HAND</small><b>{step===2?'Click Speed':step===3?'Now click Interval Training':'You spent all 3 Energy and created a synergy'}</b></div><div className="tutorial-energy"><Flame/> ENERGY <strong>{GAME_RULES.energyPerRound-selected.reduce((sum,id)=>sum+(cards.find(c=>c.id===id)?.cost||0),0)}</strong><span>/ {GAME_RULES.energyPerRound}</span></div></div><div className="hand">{drafted.map(id=>cards.find(card=>card.id===id)!).filter(Boolean).map(card=>{const isSelected=selected.includes(card.id),target=TUTORIAL_RULES.requiredCardIds[step-2]===card.id;return <div className={`tutorial-card-wrap ${isSelected?'selected':''} ${target?'target':''}`} key={card.id}><CardView card={card} disabled={!target||isSelected||step===4} play={()=>playTutorialCard(card)}/>{target&&<span className="click-me">CLICK ME</span>}</div>})}</div></section>}</main>
}
function How({replayTutorial}:{replayTutorial:()=>void}){const guideIcons={draft:BookOpen,energy:BatteryCharging,combine:Zap,respond:Activity,knowledge:Brain,compete:Trophy};return <section className="page how-page"><div className="how-hero"><div><div className="eyebrow">TACTICAL BRIEFING // LIVE ENGINE RULES</div><h2>YOU PLAY FROM THE LEFT.</h2><p className="lead">Draft your own plan, respond to the sporting situation and finish with the highest {GAME_RULES.performanceLabel}.</p></div><button className="primary" onClick={replayTutorial}><Target/> PLAY GUIDED TUTORIAL</button></div><div className="side-guide"><div className="side-player"><small>YOUR ATHLETE</small><b>YOU</b><span>Draft and play cards</span></div><ArrowRight/><div className="side-centre"><small>THE BATTLE</small><b>{GAME_RULES.rounds} ROUNDS</b><span>{GAME_RULES.energyPerRound} Energy per round</span></div><ArrowRight/><div className="side-cpu"><small>OPPOSITION</small><b>CPU</b><span>Scout its likely move</span></div></div><div className="draft-rule"><BookOpen/><div><small>PRE-MATCH DRAFT</small><h3>FIVE APPEAR. YOU CHOOSE TWO.</h3><p>Repeat this for five rounds to build a ten-card plan. Unchosen cards disappear, so use the artwork, effects, Energy costs and your GCSE PE knowledge to spot useful links. No cards are automatically selected.</p></div><strong>5 <span>OFFERS</span><i>→</i> 2 <span>PICKS</span></strong></div><h3 className="section-title">THE GAME SEQUENCE</h3><div className="steps engine-steps">{HOW_TO_PLAY_STEPS.map(step=>{const Icon=guideIcons[step.icon as keyof typeof guideIcons];return <article key={step.number}><div className="step-icon"><Icon size={28}/><span>{step.number}</span></div><h3>{step.title}</h3><p>{step.description}</p></article>})}</div><div className="how-example"><div><small>EXAMPLE COMBINATION</small><h3>SPEED + INTERVAL TRAINING</h3><p>Draft both concepts, then spend 1 + 2 Energy to activate <b>Repeat Speed</b>. Related GCSE PE concepts create the largest Performance bonuses.</p></div><div className="example-cards"><span>SPEED <b>1<Flame/></b></span><i>+</i><span>INTERVAL TRAINING <b>2<Flame/></b></span><i>=</i><strong><Zap/> REPEAT SPEED</strong></div></div><h3 className="section-title">WHAT THE CARDS TEACH</h3><div className="category-guide">{CARD_CATEGORY_GUIDE.map(category=><article className={category.id} key={category.id}><span>{category.id==='physiology'?<HeartPulse/>:category.id==='recovery'?<HeartPulse/>:category.id==='psychology'?<Brain/>:category.id==='training'?<Activity/>:<Zap/>}</span><div><b>{category.label}</b><p>{category.description}</p></div></article>)}</div><div className="tip"><CircleHelp/><div><b>THE NUMBERS</b><p>The large number beside each athlete is their current Performance Score. Confidence helps the final score; Fatigue and Injury Risk reduce it.</p></div></div></section>}
function ProfileView({profile}:{profile:Profile}){
 const history=profile.matchHistory||[];
 const knowledgeAccuracy=profile.questionsAnswered?Math.round(profile.questionsCorrect/profile.questionsAnswered*100):0;
 const winRate=profile.battles?Math.round(profile.wins/profile.battles*100):0;
 const averageScore=history.length?Math.round(history.reduce((sum,match)=>sum+match.score,0)/history.length):0;
 const averageAccuracy=history.length?Math.round(history.reduce((sum,match)=>sum+match.accuracy,0)/history.length):knowledgeAccuracy;
 const totalCombos=history.reduce((sum,match)=>sum+match.combos,0);
 const bestScore=history.length?Math.max(...history.map(match=>match.score)):0;
 const streak=history.findIndex(match=>!match.win)===-1?history.filter(match=>match.win).length:history.findIndex(match=>!match.win);
 const sportCounts=history.reduce<Record<string,number>>((counts,match)=>({...counts,[match.sport]:(counts[match.sport]||0)+1}),{});
 const favouriteSport=Object.entries(sportCounts).sort((a,b)=>b[1]-a[1])[0]?.[0]||'Play a battle';
 const recentForm=history.slice(0,5);
 const topMatches=[...history].sort((a,b)=>b.score-a.score||b.accuracy-a.accuracy).slice(0,8);
 const recentMatches=history.slice(0,6);
 const trend=history.slice(0,8).reverse();
 const trendMax=Math.max(100,...trend.map(match=>match.score));
 const sportBreakdown=Object.entries(sportCounts).sort((a,b)=>b[1]-a[1]).slice(0,6);
 const metrics=[
  {label:'BATTLES',value:profile.battles,detail:`${profile.wins} victories`},
  {label:'WIN RATE',value:`${winRate}%`,detail:`${profile.battles-profile.wins} defeats`},
  {label:'AVG PERFORMANCE',value:averageScore,detail:`Best ${bestScore}`},
  {label:'PE ACCURACY',value:`${averageAccuracy}%`,detail:`${profile.questionsCorrect}/${profile.questionsAnswered} correct`},
  {label:'COMBOS FOUND',value:totalCombos,detail:'Across saved matches'},
  {label:'WIN STREAK',value:streak,detail:'Current run'},
  {label:'CAREER WINS',value:profile.career.careerWins,detail:`${profile.career.badges.length} badges`},
  {label:'MOST PLAYED',value:favouriteSport,detail:'Preferred athlete type'}
 ];
 const dateLabel=(value:string)=>new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short'}).format(new Date(value));
 return <section className="page performance-page">
  <div className="dashboard-heading"><div><div className="eyebrow">PLAYER DOSSIER // PERFORMANCE ANALYTICS</div><h2>{profile.name}</h2><p className="lead">Track your sporting decisions, GCSE PE accuracy, combinations and best battle performances.</p></div><div className="recent-form"><small>RECENT FORM</small><div>{recentForm.length?recentForm.map(match=><i className={match.win?'win':'loss'} key={match.id}>{match.win?'W':'L'}</i>):<span>NO MATCHES YET</span>}</div></div></div>
  <div className="player-overview">
   <article className="rank performance-rank"><Trophy/><span>COACH LEVEL {Math.floor(profile.xp/250)+1}</span><b>{profile.xp} XP</b><div><i style={{width:`${profile.xp%250/2.5}%`}}/></div><small>{250-profile.xp%250} XP TO NEXT LEVEL</small></article>
   <div className="performance-kpis">{metrics.map(metric=><article key={metric.label}><small>{metric.label}</small><b className={typeof metric.value==='string'&&metric.value.length>8?'text-value':''}>{metric.value}</b><span>{metric.detail}</span></article>)}</div>
  </div>
  <div className="analytics-grid">
   <article className="analytics-panel trend-panel"><header><span><small>PERFORMANCE TREND</small><b>LAST {trend.length||0} BATTLES</b></span><Activity/></header>{trend.length?<div className="trend-chart">{trend.map(match=><div key={match.id} title={`${match.sport}: ${match.score}`}><span style={{height:`${Math.max(8,match.score/trendMax*100)}%`}} className={match.win?'win':'loss'}><b>{match.score}</b></span><small>{dateLabel(match.playedAt)}</small></div>)}</div>:<div className="empty-analytics"><Activity/><b>YOUR TREND STARTS HERE</b><span>Complete a battle to record performance.</span></div>}</article>
   <article className="analytics-panel knowledge-panel"><header><span><small>KNOWLEDGE TRACKER</small><b>GCSE PE APPLICATION</b></span><Brain/></header><div className="knowledge-score"><strong>{knowledgeAccuracy}%</strong><span>ALL-TIME ACCURACY</span></div><div className="knowledge-bars"><div><span>ANSWERS ATTEMPTED <b>{profile.questionsAnswered}</b></span><i><em style={{width:`${Math.min(100,profile.questionsAnswered*5)}%`}}/></i></div><div><span>CORRECT RESPONSES <b>{profile.questionsCorrect}</b></span><i><em style={{width:`${knowledgeAccuracy}%`}}/></i></div></div><p>Written and multiple-choice responses are saved after each completed battle.</p></article>
   <article className="analytics-panel sport-panel"><header><span><small>ATHLETE USAGE</small><b>SPORT BREAKDOWN</b></span><Target/></header>{sportBreakdown.length?<div className="sport-breakdown">{sportBreakdown.map(([sport,count])=><div key={sport}><span>{sport}<b>{count}</b></span><i><em style={{width:`${count/Math.max(...sportBreakdown.map(([,n])=>n))*100}%`}}/></i></div>)}</div>:<div className="empty-analytics"><Target/><b>CHOOSE YOUR FIRST ATHLETE</b><span>Your most-played sports will appear here.</span></div>}</article>
  </div>
  <section className="leaderboard-panel"><div className="leaderboard-heading"><div><small>THIS DEVICE // PERSONAL BESTS</small><h3>BATTLE LEADERBOARD</h3><p>Your highest saved match scores. A shared class leaderboard will require online student accounts or a school database.</p></div><Crown/></div>{topMatches.length?<div className="leaderboard-table"><div className="leaderboard-row labels"><span>RANK</span><span>ATHLETE</span><span>RESULT</span><span>PE ACCURACY</span><span>COMBOS</span><span>SCORE</span></div>{topMatches.map((match,index)=>{const athlete=athletes.find(item=>item.id===match.athleteId);return <div className={`leaderboard-row ${index<3?'podium':''}`} key={match.id}><strong>#{index+1}</strong><span className="leader-athlete">{athlete&&<img src={athlete.image} alt=""/>}<span><b>{match.sport}</b><small>{dateLabel(match.playedAt)} • {match.career?'CAREER':'QUICK'}</small></span></span><span className={match.win?'result-win':'result-loss'}>{match.win?'WIN':'LOSS'} {match.score}–{match.opponentScore}</span><span>{match.accuracy}%</span><span>{match.combos}</span><b>{match.score}</b></div>})}</div>:<div className="leaderboard-empty"><Trophy/><h3>NO SCORES RECORDED YET</h3><p>Finish a battle and your result will take the first position.</p></div>}</section>
  <section className="recent-battles"><div className="section-title">RECENT MATCH DETAILS</div>{recentMatches.length?<div>{recentMatches.map(match=><article key={match.id}><span className={match.win?'win':'loss'}>{match.win?'W':'L'}</span><div><b>{match.sport}</b><small>{match.bestCombo} • {match.combos} COMBOS</small></div><div><strong>{match.score}</strong><small>PERFORMANCE</small></div><div><strong>{match.accuracy}%</strong><small>PE ACCURACY</small></div><time>{dateLabel(match.playedAt)}</time></article>)}</div>:<p>New match records will appear here automatically.</p>}</section>
  <p className="disclaimer">Statistics and leaderboard entries are stored on this device. This independent revision resource is not affiliated with or endorsed by AQA.</p>
 </section>
}

function StatBar({label,value,kind}:{label:string;value:number;kind:string}){return <div className="statbar"><span>{label}</span><div><i className={kind} style={{width:`${clamp(value)}%`}}/></div><b>{Math.round(value)}</b></div>}
function ComboScoreBreakdown({feedback}:{feedback:ComboFeedback}){return <div className="combo-breakdown"><div className="combo-breakdown-head"><span><small>GCSE PE LINK ACTIVATED</small><b>{feedback.name}</b></span><strong>+{feedback.totalPoints}<small>{feedback.multiplier>1?'DOUBLE IMPACT':'COMBO VALUE'}</small></strong></div><p>{feedback.explanation}</p><div className="score-equation"><span>COMBO CARDS <b>+{feedback.cardPoints}</b></span><i>+</i><span>SYNERGY BONUS <b>+{feedback.synergyPoints}</b></span>{feedback.multiplier>1?<><i>×</i><strong>2 = +{feedback.totalPoints}</strong></>:<><i>=</i><strong>+{feedback.totalPoints} PERF</strong></>}</div></div>}
function BattlePowerUps({inventory,b,activate}:{inventory:PowerUpInventory;b:BattleState;activate:(id:PowerUpId)=>void}){
 const phase=b.phase==='question'?'question':b.phase==='open'?'open':b.phase==='play'?'play':null;
 if(!phase)return null;
 const available=powerUps.filter(powerUp=>powerUp.phase===phase&&(inventory[powerUp.id]||0)>0);
 if(!available.length)return null;
 return <div className={`battle-powerups ${phase}`}><small><Sparkles/> POWER-UPS</small>{available.map(powerUp=>{const disabled=powerUp.id==='double-impact'&&b.roundMultiplier>1||powerUp.id==='written-hint'&&!!b.writtenHint||powerUp.id==='fifty-fifty'&&b.eliminatedOptions.length>0;return <button key={powerUp.id} disabled={disabled} title={powerUp.description} onClick={()=>activate(powerUp.id)}><PowerUpIcon powerUp={powerUp}/><span><b>{powerUp.name}</b><em>{powerUp.strap}</em></span><strong>×{inventory[powerUp.id]}</strong></button>})}</div>;
}
function Battle({b,careerNode,powerUpInventory,activatePowerUp,playCard,launchEvent,chooseEvent,answer,submitOpenAnswer,continueOpenResult,skipTacticalCall,aiTurn}:{b:BattleState;careerNode:CareerNode|null;powerUpInventory:PowerUpInventory;activatePowerUp:(id:PowerUpId)=>void;playCard:(c:Card)=>void;launchEvent:()=>void;chooseEvent:(i:number)=>void;answer:(s:string)=>void;submitOpenAnswer:(s:string)=>void;continueOpenResult:()=>void;skipTacticalCall:()=>void;aiTurn:()=>void}){
 const event=events[b.eventIndex];
 const intel=opponentIntent(b.opponent,b.round);
 return <main className="battle" style={{'--accent':b.athlete.accent} as React.CSSProperties}>
  <div className="battle-top"><div className="battle-brand"><Zap/> PE//BATTLE {careerNode&&<span>// {careerNode.title}</span>}</div><div className="rounds"><small>ROUND</small>{Array.from({length:GAME_RULES.rounds},(_,i)=>i+1).map(n=><i key={n} className={n<=b.round?'on':''}>{n}</i>)}</div><div className="opponent-label">VS CPU // {careerNode?.type==='championship'?'THE CHAMPION':'COACH NOVA'}</div></div>
  <section className="arena"><AthletePanel athlete={b.athlete} stats={b.stats}/><div className="centre-stage">
   {b.phase==='play'?<><div className="phase-label">BUILD PHASE</div><div className="opponent-intent"><Shield/><div><small>SCOUT REPORT // OPPONENT INTENT</small><b>{intel.name}</b><span>{intel.detail}</span></div><strong>{intel.projected}<small>PROJECTED</small></strong></div><div className={`combo-space ${b.comboFeedback?'showing-breakdown':''}`}>{b.comboFeedback?<ComboScoreBreakdown feedback={b.comboFeedback}/>:b.played.length===0?<><Target/><b>BUILD YOUR COMBINATION</b><span>Spend Energy on the strongest training link</span></>:<div className="played-row">{b.played.map(c=><MiniCard key={c.id} card={c}/>)}</div>}</div><button className="event-button" onClick={launchEvent}>LOCK IN &amp; COMPETE <ArrowRight/></button></>
   :b.phase==='event'?<Modal title={event.title} tag={`${b.athlete.sport.toUpperCase()} // MATCH MOMENT`} icon={<Activity/>}><p>{contextualEventDescription(event,b.athlete)}</p><div className="decision-label">MAKE THE COACHING CALL</div><div className="choices">{event.choices.map((c,i)=><button key={c.text} onClick={()=>chooseEvent(i)}><span>{String.fromCharCode(65+i)}</span>{c.text}<ArrowRight/></button>)}</div></Modal>
   :b.phase==='question'&&b.question?<Modal title="TACTICAL GAMBLE" tag={`OPTIONAL • ${b.question.ao} • +${10*b.roundMultiplier} PERFORMANCE`} icon={<Brain/>}><p className="gamble-copy">Back your PE knowledge for a performance boost, or protect momentum and pass.</p><BattlePowerUps inventory={powerUpInventory} b={b} activate={activatePowerUp}/><p>{b.question.question}</p><div className="choices compact">{b.question.options.map((o,i)=><button className={b.eliminatedOptions.includes(o)?'eliminated':''} disabled={b.eliminatedOptions.includes(o)} key={o} onClick={()=>answer(o)}><span>{String.fromCharCode(65+i)}</span>{b.eliminatedOptions.includes(o)?'REMOVED BY 50:50 SCANNER':o}</button>)}</div><button className="pass-button" onClick={skipTacticalCall}>PASS — PROTECT MOMENTUM</button></Modal>
   :b.phase==='open'&&b.openQuestion?<OpenResponse question={b.openQuestion} multiplier={b.roundMultiplier} hint={b.writtenHint} powerUps={<BattlePowerUps inventory={powerUpInventory} b={b} activate={activatePowerUp}/>} submit={submitOpenAnswer} pass={skipTacticalCall}/>
   :b.phase==='open-result'&&b.openQuestion&&b.openResult?<OpenResult question={b.openQuestion} result={b.openResult} continueBattle={continueOpenResult}/>
   :<Modal title="OPPOSITION MOVE" tag="CPU TURN" icon={<Shield/>}><div className={`decision-outcome ${b.log[0]?.startsWith('OPTIMAL')?'optimal':b.log[0]?.startsWith('WEAK')?'weak':'useful'}`}><small>YOUR LAST CALL</small><b>{b.log[0]}</b></div><p>Coach Nova is responding with its own training plan.</p><div className="ai-thinking"><i/><i/><i/></div><button className="event-button" onClick={aiTurn}>{b.round===GAME_RULES.rounds?'CALCULATE FINAL PERFORMANCE':'RESOLVE CPU TURN'} <ArrowRight/></button></Modal>}
  </div><AthletePanel athlete={b.opponent} stats={b.ai} opponent/></section>
  {b.phase==='play'&&<section className="hand-area"><div className="hand-head"><div><small>YOUR HAND // YOU ARE ON THE LEFT</small><b>Click cards totalling up to your available Energy, then lock in {b.roundMultiplier>1&&'• DOUBLE IMPACT ACTIVE'}</b></div><div className="round-plan"><span>BUILD</span><i>→</i><span>RESPOND</span>{(b.round===2||b.round===4)&&<><i>→</i><span className="hot">GAMBLE</span></>}<i>→</i><span>COMPETE</span></div><BattlePowerUps inventory={powerUpInventory} b={b} activate={activatePowerUp}/><div className="energy"><Flame/> ENERGY <strong>{b.stats.energy}</strong><span>/ {GAME_RULES.energyPerRound}{b.stats.energy>GAME_RULES.energyPerRound?' + BOOST':''}</span></div></div><div className="hand">{b.hand.map(c=><CardView key={c.id} card={c} disabled={c.cost>b.stats.energy} play={()=>playCard(c)}/>)}</div></section>}
 </main>
}
function AthletePanel({athlete,stats,opponent=false}:{athlete:Athlete;stats:Stats;opponent?:boolean}){return <aside className={`athlete-panel ${opponent?'cpu':'player-side'}`} style={{'--accent':athlete.accent} as React.CSSProperties}><div className="athlete-art"><img src={athlete.image} alt={`Fictional ${athlete.sport}`}/><small>{opponent?'OPPOSITION':'YOU // YOUR ATHLETE'}</small><em>{overall(athlete)} OVR</em></div><div className="athlete-id"><div><b>{athlete.name}</b><span>{athlete.sport}</span></div><strong><small>PERF</small>{Math.round(stats.performance)}</strong></div><StatBar label="CONF" value={stats.confidence} kind="good"/><StatBar label="FATIGUE" value={stats.fatigue} kind="warn"/><StatBar label="INJURY" value={stats.injuryRisk} kind="danger"/></aside>}
function CardArtwork({card}:{card:Card}){const art=cardArt(card.id);return art?<div className="card-art" role="img" aria-label={art.alt} style={{backgroundImage:`url(${art.sheet})`,backgroundPosition:art.position}}/>:null}
function CardView({card,disabled,play}:{card:Card;disabled:boolean;play:()=>void}){return <button className={`game-card ${card.type}`} disabled={disabled} onClick={play}><div className="card-top"><span>{card.type}</span><b>{card.cost}<Flame/></b></div><CardArtwork card={card}/><h3>{card.name}</h3><p>{card.effect}</p><footer><strong>+{card.performance}</strong> PERFORMANCE</footer></button>}
function MiniCard({card}:{card:Card}){return <div className={`mini-card ${card.type}`}><CardArtwork card={card}/><small>{card.type}</small><b>{card.name}</b></div>}
function OpenResponse({question,multiplier,hint,powerUps:powerUpControls,submit,pass}:{question:OpenQuestion;multiplier:number;hint:string|null;powerUps:React.ReactNode;submit:(value:string)=>void;pass:()=>void}){const [response,setResponse]=useState('');return <div className="event-modal open-response"><div className="modal-icon"><Brain/></div><small>AQA GCSE PE 8582-ALIGNED PRACTICE • {question.ao} • UP TO +{10*multiplier} PERFORMANCE</small><h2>MAKE THE CASE</h2><div className="scenario-strip"><Activity/><span><b>SPORTING SITUATION</b>{question.scenario}</span></div><p className="open-prompt">{question.prompt}</p>{powerUpControls}{hint&&<div className="written-hint"><Brain/><span><small>WRITTEN HINT REVEALED</small><b>Try to include: {hint}</b><em>Explain the link rather than copying the phrase on its own.</em></span></div>}<div className="response-box"><textarea autoFocus value={response} maxLength={420} onChange={e=>setResponse(e.target.value)} placeholder="Explain your decision using GCSE PE knowledge…"/><div><span>{response.length} / 420</span><span>{question.markPoints.length} authored concepts available</span></div></div><div className="open-actions"><button className="pass-button" onClick={pass}>PASS — NO BONUS</button><button className="event-button" disabled={response.trim().length<12} onClick={()=>submit(response)}>ASSESS PRACTICE RESPONSE <ArrowRight/></button></div><small className="game-score-note">Independent AQA 8582-aligned practice feedback — not an official examination mark</small></div>}
function OpenResult({question,result,continueBattle}:{question:OpenQuestion;result:MarkResult;continueBattle:()=>void}){return <div className="event-modal open-result"><div className="result-header"><div className="score-ring" style={{'--score':`${result.score*3.6}deg`} as React.CSSProperties}><strong>{result.score}%</strong><small>PRACTICE SCORE</small></div><div><small>AQA GCSE PE 8582-ALIGNED PRACTICE</small><h2>{result.band}</h2><p>+{result.performanceBonus} Performance earned</p></div></div><div className="assessment-summary"><div><span>ESTIMATED PRACTICE MARK</span><b>{result.practiceMark} / {result.maxMark}</b></div><div><span>LEVEL-STYLE OUTCOME</span><b>LEVEL {result.practiceLevel}</b></div><div><span>MATCH CONFIDENCE</span><b className={result.confidence.toLowerCase()}>{result.confidence}</b></div><div><span>ASSESSMENT OBJECTIVE</span><b>{question.ao}</b></div></div><p className="level-descriptor">{result.descriptor}</p><div className="concept-columns"><div><small>AUTHORED POINTS RECOGNISED</small>{result.matched.length?result.matched.map(point=><span className="hit" key={point.id}><Check/>{point.label}</span>):<p>No clear mark points detected yet.</p>}</div><div><small>DEVELOP NEXT</small>{result.missed.length?result.missed.map(point=><span className="miss" key={point.id}>+ {point.label}</span>):<p>All available concepts recognised.</p>}</div></div>{result.misconceptions.length>0&&<div className="misconception"><b>CHECK THIS IDEA</b>{result.misconceptions.join(' • ')}</div>}<div className="model-answer"><small>EXAMPLE OF A STRONG RESPONSE</small><p>{question.modelAnswer}</p><span>{question.explanation}</span></div><button className="event-button" onClick={continueBattle}>TAKE THE SCORE <ArrowRight/></button><small className="game-score-note">Estimated independent practice feedback. Not official AQA marking or endorsement.</small></div>}
function Modal({title,tag,icon,children}:{title:string;tag:string;icon:React.ReactNode;children:React.ReactNode}){return <div className="event-modal"><div className="modal-icon">{icon}</div><small>{tag}</small><h2>{title}</h2>{children}</div>}
function Report({r,profile,again,home,continueCareer}:{r:{win:boolean;score:number;ai:number;xp:number;accuracy:number;best:string;topic:string;careerNodeId:string|null};profile:Profile;again:()=>void;home:()=>void;continueCareer?:()=>void}){return <main className={`report ${r.win?'victory':'defeat'}`}><div className="report-glow"/><button className="logo report-logo" onClick={home}><Zap/> GCSE PE <b>BATTLE</b></button><section><div className="result-icon">{r.win?<Trophy/>:<Shield/>}</div><div className="eyebrow">{r.careerNodeId?`${careerNodes.find(n=>n.id===r.careerNodeId)?.title} // `:''}MATCH COMPLETE</div><h1>{r.win?'VICTORY':'DEFEAT'}</h1><p>{r.win?'Preparation beats pressure. Outstanding work.':'The margins were tight. Adapt and return stronger.'}</p><div className="scoreline"><div><small>{profile.name}</small><b>{r.score}</b><span>PERFORMANCE</span></div><i>—</i><div><small>COACH NOVA</small><b>{r.ai}</b><span>PERFORMANCE</span></div></div><div className="report-stats"><div><Brain/><span>PE ACCURACY</span><b>{r.accuracy}%</b></div><div><Zap/><span>BEST COMBO</span><b>{r.best}</b></div><div><Flame/><span>XP EARNED</span><b>+{r.xp}</b></div></div><div className="practice"><Target/><div><small>TOPIC TO PRACTISE NEXT</small><b>{r.topic}</b></div></div><div className="actions">{continueCareer?<button className="primary" onClick={continueCareer}><Sparkles/> CLAIM CAREER REWARD <ArrowRight/></button>:<button className="primary" onClick={again}><RotateCcw/> {r.careerNodeId?'RETRY NODE':'PLAY AGAIN'}</button>}<button className="secondary" onClick={home}>{r.careerNodeId?<Map/>:<Home/>} {r.careerNodeId?'VIEW ROUTE':'RETURN HOME'}</button></div></section></main>}
export default App;
